def numberOfComponents(properties: List[List[int]], k: int) -> int:
    n = len(properties)
    # 將每個子陣列轉為 set 以方便計算交集
    sets = [set(p) for p in properties]

    # 使用 Adjacency List 建立圖
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            # 計算交集數量
            if len(sets[i].intersection(sets[j])) >= k:
                adj[i].append(j)
                adj[j].append(i)

    visited = [False] * n
    count = 0

    # BFS 或 DFS 遍歷找出連通分量
    for i in range(n):
        if not visited[i]:
            count += 1
            stack = [i]
            visited[i] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

    return count
