from typing import List

def maxCollectedFruits(fruits: List[List[int]]) -> int:
    n = len(fruits)
    if n == 1:
        return fruits[0][0]

    # Child 1 path is fixed to the main diagonal because they must move exactly n-1 times.
    # From (0,0) to (n-1, n-1), only steps of (+1, +1) reach it in n-1 moves.
    res = sum(fruits[i][i] for i in range(n))

    # Child 2: starts at (0, n-1), must stay in j > i region, ends at (n-1, n-1).
    # To reach (n-1, n-1) in exactly n-1 moves from row 0, each move MUST increase the row index by 1.
    # Thus: ni = i + 1 for every step.
    dp2 = [[float('-inf')] * n for _ in range(n)]
    dp2[0][n-1] = fruits[0][n-1]

    for i in range(n - 1):
        for j in range(i + 1, n):
            if dp2[i][j] == float('-inf'):
                continue
            # Possible moves for Child 2: (i+1, j-1), (i+1, j), (i+1, j+1)
            for nj in [j - 1, j, j + 1]:
                ni = i + 1
                if ni < n and nj > ni:
                    # Stay strictly above diagonal until the very last cell
                    if ni == n - 1 and nj == n - 1:
                        # This is the final step. We don't add fruits[n-1][n-1] because it's in 'res'.
                        dp2[ni][nj] = max(dp2[ni][nj], dp2[i][j])
                    else:
                        dp2[ni][nj] = max(dp2[ni][nj], dp2[i][j] + fruits[ni][nj])

    # Child 3: starts at (n-1, 0), must stay in i > j region, ends at (n-1, n-1).
    # To reach (n-1, n-1) in exactly n-1 moves from col 0, each move MUST increase the column index by 1.
    # Thus: nj = j + 1 for every step.
    dp3 = [[float('-inf')] * n for _ in range(n)]
    dp3[n-1][0] = fruits[n-1][0]

    for j in range(n - 1):
        for i in range(j + 1, n):
            if dp3[i][j] == float('-inf'):
                continue
            # Possible moves for Child 3: (i-1, j+1), (i, j+1), (i+1, j+1)
            for ni in [i - 1, i, i + 1]:
                nj = j + 1
                if nj < n and ni > nj:
                    # Stay strictly below diagonal until the very last cell
                    if nj == n - 1 and ni == n - 1:
                        dp3[ni][nj] = max(dp3[ni][nj], dp3[i][j])
                    else:
                        dp3[ni][nj] = max(dp3[ni][nj], dp3[i][j] + fruits[ni][nj])

    # The result is the sum of diagonal plus the best paths found for child 2 and 3.
    # We use max(0, ...) to handle cases where no valid path exists (though not expected here).
    final_res = res + max(0, dp2[n-1][n-1]) + max(0, dp3[n-1][n-1])
    return int(final_res)

