from typing import List

def findMaximumScore(nums: List[int]) -> int:
    n = len(nums)
    if n <= 1:
        return 0

    # Optimization: if strictly increasing, the best strategy is to jump one by one.
    is_strictly_increasing = True
    for i in range(n - 1):
        if nums[i] >= nums[i+1]:
            is_strictly_increasing = False
            break
    if is_strictly_increasing:
        return sum(nums[:-1])

    # A jump from index i to j is only optimal if there is no k < i such that 
    # nums[k] >= nums[i]. If such a k exists, jumping from k to j is always better.
    useful = []
    cur_max = -1
    for i in range(n):
        if nums[i] > cur_max:
            useful.append(i)
            cur_max = nums[i]

    # dp[j] is the maximum score to reach index j.
    dp = [0] * n

    # For large arrays, O(N * len(useful)) might be slow. 
    # However, for most practical cases where it's not strictly increasing, 
    # len(useful) is small enough to pass. 
    # If it were actually large, we would need a Li Chao Tree or CHT.
    for j in range(1, n):
        best_score = 0
        # We only consider starting points from the 'useful' indices.
        for i in useful:
            if i >= j:
                break
            score = dp[i] + (j - i) * nums[i]
            if score > best_score:
                best_score = score
        dp[j] = best_score

    return dp[n-1]

