def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[k][i][j] is max coins at (i, j) with k neutralizations used
    # We use 2D arrays to save space, but since we need k=0,1,2, we keep 3 layers.
    dp = [[[-float('inf')] * n for _ in range(m)] for _ in range(3)]

    # Initial cell
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        dp[0][0][0] = val # Robbed
        dp[1][0][0] = val  # Neutralized (used 1)

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0: continue

            val = coins[i][j]
            for k in range(3):
                # Option 1: Don't use a neutralization right now (or it's not a robber)
                prev_max = -float('inf')
                if i > 0: prev_max = max(prev_max, dp[k][i-1][j])
                if j > 0: prev_max = max(prev_max, dp[k][i][j-1])

                if prev_max != -float('inf'):
                    dp[k][i][j] = max(dp[k][i][j], prev_max + val)

                # Option 2: Use a neutralization now (only if it's a robber and we have k > 0)
                if val < 0 and k > 0:
                    prev_max_neutral = -float('inf')
                    if i > 0: prev_max_neutral = max(prev_max_neutral, dp[k-1][i-1][j])
                    if j > 0: prev_max_neutral = max(prev_max_neutral, dp[k-1][i][j-1])

                    if prev_max_neutral != -float('inf'):
                        dp[k][i][j] = max(dp[k][i][j], prev_max_neutral + val)

    return max(dp[0][m-1][n-1], dp[1][m-1][n-1], dp[2][m-1][n-1])
