from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])

    # dp[i][j][k] 表示到達 (i, j) 且使用了 k 次能力的最大收益
    # 初始化為極小值，代表該狀態尚未達到
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]

    # 起點初始化
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        # 如果起點是小偷，可以選擇用一次能力中和它
        dp[0][0][1] = max(dp[0][0][1], val) # 不用能力（被搶）
        dp[0][0][1] = max(dp[0][0][1], 0)    # 用一次能力（不被搶，但因為是負數轉為0其實邏輯上是抵銷掉絕對值）
        # 修正：題目說中和小偷是「防止他偷錢」，所以如果 coins < 0，中和後收益就是 0。
        dp[0][0][1] = max(dp[0][0][1], 0) # 這裡其實應該是處理負數變為0的情況

    # 正確的起點邏輯：
    # 如果 coins[0][0] >= 0, dp[0][0][0] = coins[0][0]
    # 如果 coins[0][0] < 0:
    #   dp[0][0][0] = coins[0][0] (沒用能力)
    #   dp[0][0][1] = 0 (用了能力，負數變為0)

    # 重寫起點邏輯確保正確：
    if coins[0][0] >= 0:
        dp[0][0][0] = coins[0][0]
    else:
        dp[0][0][0] = coins[0][0] # 不用能力，被搶
        dp[0][0][1] = 0            # 用一次能力，不被搶 (收益為 0)

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0: continue

            current_val = coins[i][j]
            for k in range(3):
                # 從上方來的選擇
                res_up = -float('inf')
                if i > 0:
                    # 1. 上方沒用能力中和當前格子 (或當前格子不是小偷)
                    if current_val >= 0:
                        res_up = max(res_up, dp[i-1][j][k] + current_val)
                    else:
                        # 如果是小偷，沒用能力就加原本的負數
                        res_up = max(res_up, dp[i-1][j][k] + current_val)

                    # 2. 上方已經用了 k-1 次，現在在當前格子（若是小偷）用第 k 次
                    if k > 0 and current_val < 0:
