            for j in range(m):
                if res[i + j] is not None and res[i + j] != str2[j]:
                    return ""
                res[i + j] = str2[j]

    # Step 2: Check for consistency of 'T' overlapping constraints
    # (Actually handled by the loop above, but let's ensure we didn't miss any)

    # Step 3: Greedily fill remaining positions with 'a'
    for i in range(total_len):
        if res[i] is None:
            res[i] = 'a'

    # Step 4: Validate all constraints (T and F)
    # A string satisfies T if word[i...i+m-1] == str2
    # A string satisfies F if word[i...i+m-1] != str2

    # First, check T conditions. If a 'T' was present but the result 
    # doesn't match str2, it means the greedy fill or initial T fill failed.
    for i in range(n):
        if str1[i] == 'T':
            current_sub = "".join(res[i : i + m])
            if current_sub != str2:
                return ""

    # Second, check F conditions. 
    # If an 'F' condition is violated (word == str2), we must change one char.
    # To keep it lexicographically smallest, we try to change the rightmost possible char.
    for i in range(n):
        if str1[i] == 'F':
            current_sub = "".join(res[i : i + m])
            if current_sub == str2:
                # Must change one character in res[i...i+m-1] to make it != str2
                # while maintaining T constraints.
                changed = False
                for j in range(i, i + m):
                    # Can we change res[j]? 
                    # It's safe to change if:
                    # 1. It wasn't fixed by a 'T' constraint.
                    # 2. Changing it doesn't violate any other 'T' constraints.

                    # Actually, the only way res[j] is "fixed" is if there exists k
                    # such that str1[k] == 'T' and j is in [k, k+m-1].
                    is_fixed = False
                    for k in range(max(0, j - m + 1), min(n, j + 1)):
                        if str1[k] == 'T':
                            # This position j is covered by a T at k.
                            # The value must be str2[j-k].
                            is_fixed = True
                            break

                    if not is_fixed:
                        # Try to change it to the smallest char that makes sub != str2
                        # and is lexicographically smallest overall (try 'a', then 'b'...)
                        for char_code in range(ord('a'), ord('z') + 1):
                            char = chr(char_code)
                            if char != res[j]:
                                # Temporarily change to check if it still equals str2
                                old_val = res[j]
                                res[j] = char
                                # Check if this specific index j is part of any T that now fails
                                valid = True
                                for k in range(max(0, j - m + 1), min(n, j + 1)):
                                    if str1[k] == 'T':
                                        # The substring starting at k must be exactly str2
                                        # We only need to check if the char at index (j-k) matches
                                        if res[j] != str2[j - k]:
                                            valid = False
                                            break
                                # If it doesn't violate any T and we changed a value, 
                                # but wait, we need to make sure the NEW substring at i is != str2.
                                # Actually, if we change ANY char in res[i...i+m-1] that isn't fixed,
                                # it will either become != str2 or stay = str2 (impossible since we 
                                # only change if current == str2).
                                if valid:
                                    changed = True
                                    break
                                else:
                                    res[j] = old_val
                                    break
                            else:
                                res[j] = old_val
                        if changed: break

                if not changed: # Could not modify the substring to satisfy F
                    return ""

    # Final check for all F's (in case a change made one 'F' valid but another invalid)
    for i in range(n):
        if str1[i] == 'F':
            if "".join(res[i : i + m]) == str2:
                return ""

    return "".join(res)
