    # 檢查目標 m 是否為質數 (題目要求任何一點都不可為質數)
    def is_prime(num):
        if num < 2: return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # 如果目標 m 是質數，直接回傳 -1
    if is_prime(m):
        return -1

    # 如果初始值 n 是質數，根據題目「包含原始值」，也無法開始
    if is_prime(n):
        return -1

    # 找出數字的位數（因為 n 和 m 位數相同且不可超過 10^4）
    max_val = 10000

    # Dijkstra 初始化
    # pq 儲存 (累積成本, 當前數值)
    pq = [(n, n)]
    distances = {n: n} # 這裡的 cost 是累積和，初始是 n 本身的值

    while pq:
        current_cost, curr = heapq.heappop(pq)

        if curr == m:
            return current_cost

        if current_cost > distances.get(curr, float('inf')):
            continue

        # 嘗試所有可能的數字變動
        # 因為 n, m < 10^4，我們檢查鄰近的數值
        for diff in [-1, 1]:
            nxt = curr + diff

            # 條件檢查：範圍限制、位數不變（由題目範例推論）、非質數
            if nxt > 0 and nxt < max_val:
                # 確保與 m 的位數一致 (例如從 10 變成 9 不行)
                if len(str(nxt)) == len(str(m)):
                    if not is_prime(nxt):
                        new_cost = current_cost + nxt
                        if new_cost < distances.get(nxt, float('inf')):
                            distances[nxt] = new_cost
                            heapq.heappush(pq, (new_cost, nxt))

    return -1
